"""Generate review-only balance files from the preserved workbook. Never writes runtime data/."""
import json,csv,hashlib,math
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
SRC=ROOT/'design/roster60-review/workbook-complete-proposal.json'
OUT=ROOT/'design/roster60-review/balance-v0.1';OUT.mkdir(exist_ok=True)
p=json.loads(SRC.read_text());units=p['units']
elements=['normal','fire','water','lightning','ice','nature','holy','dark']
families=[['주먹','강한주먹','맹렬한주먹','온힘의 주먹'],['불씨','불꽃이빨','불길채찍','불아귀'],['물방울','물살찌르기','너울송곳','너울어금니'],['번갯불','번개쏘기','벼락송곳','우레엄니'],['서리바늘','고드름','얼음쐐기','서릿발'],['잎날','가시꿰기','덩굴아귀','숲의 꾸짖음'],['빛살','빛살꿰기','햇무리','새벽날개'],['그늘손','그늘발톱','어둠송곳','그늘낫']]
confirmed_names={'주먹','강한주먹','맹렬한주먹','온힘의 주먹','우레엄니','숲의 꾸짖음'}
grade_codes=dict(zip(['커먼','언커먼','레어','에픽','전설','히든','제한','초월','불멸','영원'],['COMMON','UNCOMMON','RARE','EPIC','LEGEND','HIDDEN','LIMITED','TRANSCEND','IMMORTAL','ETERNAL']))
grade_bonus=dict(zip(grade_codes,[0,0,1,1,2,2,3,3,4,4]))
profiles={'balanced':[60,60,55,55],'striker':[80,55,60,45],'caster':[40,80,45,60],'hybrid':[65,65,50,50],'tank':[65,45,70,60]}
keys=['hp','mp','patk','matk','pdef','mdef']
base={'schemaVersion':'roster60-balance-draft-v0.1','approved':False,'status':'REVIEW_ONLY_NOT_RUNTIME','sourceFile':str(SRC.relative_to(ROOT)),'sourceJsonSha256':hashlib.sha256(SRC.read_bytes()).hexdigest(),'sourceWorkbookSha256ReportedByParent':p['provenance']['sourceWorkbookSha256'],'note':'Workbook numbers and recipe thresholds are review proposals. Confirmed gameplay rules do not approve all catalog values.'}
def write(name,obj): (OUT/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2)+'\n')
def half(n,d):return (2*n+d)//(2*d)
lookup={};skills=[]
for element,names in zip(elements,families):
 for tier,name in enumerate(names,1):
  id=f'{element}_{tier}';lookup[name]=id
  learned=[{'unitId':u['id'],'level':x['level'],'sourceStage':x['stage'],'sourceRow':u['sourceRow']} for u in units for x in u['learnset'] if x['name']==name]
  assert learned, name
  skills.append({'id':id,'name':name,'nameStatus':'confirmed_in_parent_history' if name in confirmed_names else 'workbook_proposal_not_name_approval','sourceVerifiedInPreservedJson':True,'element':element,'damageChannel':'physical' if element=='normal' else 'magical','tier':tier,'stage':['beginner','intermediate','advanced','ultimate'][tier-1],'power':[35,60,95,140][tier-1],'mpCost':[6,12,20,30][tier-1],'defaultLearnLevel':[1,10,24,40][tier-1],'learnedBy':learned,'target':'single_enemy','effects':[],'balanceStatus':'proposed','sourceNameConcern':'벼락송곳 is present in preserved workbook extraction; NOT one of the six explicitly confirmed names.' if name=='벼락송곳' else None})
result=[]
for u in units:
 role=u['role'];kind='balanced' if '균형' in role else 'tank' if '고체력' in role else 'hybrid' if '근접술사' in role else 'caster' if '술사' in role else 'striker'
 refs=dict(zip(keys,[u['hp'],u['mp']]+profiles[kind]))
 # Preserve integer level-one baseline and exact Lv20 reference; linear rational increment avoids cumulative rounding.
 growth={k:{'levelOneRounded':half(v*25,44),'levelOneExact':{'numerator':half(v*25,44),'denominator':1},'perLevelExact':{'numerator':v-half(v*25,44),'denominator':19}} for k,v in refs.items()}
 primary=next(e for e,names in zip(elements,families) if u['learnset'][0]['name'] in names)
 fits=dict(u['aptitudes']);fits[primary]+=grade_bonus[u['grade']]
 result.append({'id':u['id'],'name':u['name'],'identityStatus':'confirmed_u01_name' if u['id']=='u01' else 'preserved_workbook_identity_no_new_rename','grade':grade_codes[u['grade']],'sourceGrade':u['grade'],'identitySourceRow':u['sourceRow'],'role':role,'roleProfile':kind,'concept':u['concept'],'passives':[],'referenceLevel':20,'referenceStats':refs,'referenceStatus':{'hp_mp':'source_workbook_proposal','other_four':'new_role_profile_proposal'},'levelOneStats':{k:v['levelOneRounded'] for k,v in growth.items()},'growth':growth,'primarySkillElement':primary,'sourceSuitability':u['aptitudes'],'suitability':fits,'suitabilityProposal':{'gradeBandAddition':grade_bonus[u['grade']],'appliedTo':primary,'status':'proposed'},'defense':{k:('immune' if v=='null' else v) for k,v in u['defenses'].items()},'defenseStatus':'source_workbook_proposal','learnset':[{'skillId':lookup[x['name']],'level':x['level'],'sourceStage':x['stage']} for x in u['learnset']],'skillSlotCapacity':6,'basicAttackId':'basic_attack','rebirthAllowed':grade_codes[u['grade']] in ['LIMITED','TRANSCEND','IMMORTAL','ETERNAL'],'budgetComparison':{'sourceHpPlusFourMp':u['hp']+4*u['mp'],'referenceOnlyNotApprovedConstraint':600},'balanceStatus':'proposed'})
normal=[0];reborn=[0]
for level in range(1,99):
 need=math.floor(20*level**1.5+0.5);normal.append(normal[-1]+need);reborn.append(reborn[-1]+((need*70+99)//100 if level<60 else need))
policy={**base,'confirmed':{'elements':elements,'maxLevelOrdinary':60,'maxLevelReborn':99,'rebirthAllowedGrades':['LIMITED','TRANSCEND','IMMORTAL','ETERNAL'],'rebirthRequiredLevels':[60,70,80,90,99],'maxRebirths':5,'rebirthAdditiveBasePercentEach':10,'rebirthResetLevel':1,'rebirthResetCurrentCycleXp':0,'rebirthAccountFirstSuccessFree':True,'rebirthLaterPeanutCost':1,'rebirthEarlyRequirementPercent':70,'rebirthEarlyRequirementCurrentLevels':[1,59],'suitabilityDamagePerPoint':0.1,'defenseMultipliers':{'weak':1.5,'normal':1,'resist':0.5,'immune':0},'reflectNoTargetDamage':True,'reflectNoChain':True,'extraTurnOnWeakness':False,'startMp':'full','focusRecoveryFraction':0.25,'focusUsesAction':True,'skillSlotCapacity':6,'craftXp':'floor(sum(currentCycleTotalXp)/materialInstanceCount)','creatureElement':None},'proposed':{'statGrowth':{'formula':'roundHalfUp(baseLevelOne * (100+10*rebirthCount)/100) + roundHalfUp((referenceLevel20Stat-baseLevelOne)*(level-1)/19)','rounding':'round baseline bonus and independent growth contribution separately; no recursive rounding or growth multiplier','levelOneAndGrowthRationals':'Integer levelOneStats is authoritative; per-level rational increment reaches the original Lv20 value exactly. Rebirth uses this integer baseline, matching the existing server bonus contract.'},'roleProfilesLevel20':{k:dict(zip(keys[2:],v)) for k,v in profiles.items()},'xp':{'normalNextRequirement':'roundHalfUp(20*currentLevel^1.5)','normalCumulativeThresholds':normal,'rebornCumulativeThresholds':reborn,'rebornRounding':'ceil(each normal requirement * 0.70) for currentLevel<60; no earned multiplier','winAward':'60*enemyLevel','lossAward':'20*enemyLevel','practiceAward':0},'damage':{'base':'max(1,floor(power * offense / (targetDefense + 40)))','physical':['patk','pdef'],'magical':['matk','mdef'],'suitability':'max(0,1+0.10*value)','final':'floor(base * suitabilityMultiplier * defenseMultiplier), clamp to remaining HP','immunity':'always zero; bypass base minimum damage','reflection':'floor(base * suitabilityMultiplier), computed against original target defense, returned to attacker; no attacker defense re-evaluation; no secondary status, lifesteal or hit triggers'},'basicAttack':{'id':'basic_attack','name':'공격','element':'normal','damageChannel':'physical','power':20,'mpCost':0,'target':'single_enemy'},'accuracyPercent':100,'criticalChancePercent':0,'damageVariancePercent':0,'turnOrder':'player first in tutorial/PvE; alternating actions','speedStat':None,'turnLimitActions':200,'turnLimitOutcome':'draw; no win reward','equipPolicy':'all learned skills up to6; workbook supplies5, sixth remains empty','focusRounding':'floor(maxMP/4); clamp to maxMP','invalidAction':'reject without spending MP or advancing turn'},'unresolved':['Approval of all proposed numeric values and generated catalog','Skill names other than six explicitly confirmed names, including 벼락송곳','Missing HP/MP/base-stat growth approval and role four-stat proposal','Excess XP at cap: reject/hold unsupported overflow; no silent discard/bank policy','Rebirth eligibility inheritance through crafting; currently block reborn materials','PvP turn order and opponent content; only PvE test order proposed','Item values, reserve-party size/swap and escape detailed rules','Augment catalog and modifier order; simulations have no augments','Skill replacement/inheritance when future learnsets exceed6; do not silently truncate','Costs/rewards beyond confirmed rebirth peanut policy'], 'noConceptPassives':'Concept words such as regeneration/revival/sealing are not executable effects.'}
write('complete60-unit-data.draft.json',{**base,'units':result})
write('skills32.draft.json',{**base,'skills':skills})
write('policies.draft.json',policy)
write('recipes52.source-review.json',{**base,'status':'SOURCE_REVIEW_RECIPES_NOT_NEW_APPROVAL','recipes':p['recipes']})
with (OUT/'complete60-unit-data.draft.csv').open('w',newline='') as f:
 fields=['id','name','grade','roleProfile']+[f'lv1_{k}' for k in keys]+[f'lv20_{k}' for k in keys]+[f'growth_{k}_per_level' for k in keys]+['primaryElement','primarySuitability','learnset','approved']
 w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
 for u in result:w.writerow({'id':u['id'],'name':u['name'],'grade':u['grade'],'roleProfile':u['roleProfile'],**{f'lv1_{k}':u['levelOneStats'][k] for k in keys},**{f'lv20_{k}':u['referenceStats'][k] for k in keys},**{f'growth_{k}_per_level':f"{u['growth'][k]['perLevelExact']['numerator']}/19" for k in keys},'primaryElement':u['primarySkillElement'],'primarySuitability':u['suitability'][u['primarySkillElement']],'learnset':';'.join(f"{x['level']}:{x['skillId']}" for x in u['learnset']),'approved':'false'})
with (OUT/'skills32.draft.csv').open('w',newline='') as f:
 fields=['id','name','nameStatus','element','damageChannel','tier','power','mpCost','defaultLearnLevel','actualLearnLevels','approved'];w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
 for s in skills:w.writerow({**{k:s[k] for k in fields if k in s},'actualLearnLevels':';'.join(map(str,sorted({x['level'] for x in s['learnedBy']}))),'approved':'false'})
print(f'Wrote {len(result)} units, {len(skills)} skills, {len(p["recipes"])} recipes; approved=false.')
